latest_checkpoint() {
  local run_dir="$1"
  if [[ -f "$run_dir/checkpoint.pt" ]]; then
    printf '%s\n' "$run_dir/checkpoint.pt"
    return 0
  fi
  find "$run_dir" -maxdepth 1 -type f -name 'checkpoint_epoch_*.pt' 2>/dev/null | sort | tail -n 1
}

checkpoint_epoch() {
  python - "$1" <<'__PY_CHECKPOINT__'
import sys, torch
p=sys.argv[1]
try:
    ck=torch.load(p,map_location='cpu',weights_only=False)
except TypeError:
    ck=torch.load(p,map_location='cpu')
print(int(ck.get('epoch',-1)))
__PY_CHECKPOINT__
}

run_logged() {
  local label="$1"; shift
  local log="$LOG_DIR/${label}.log"
  echo
  echo "============================================================"
  echo "START $label at $(date)"
  echo "LOG   $log"
  echo "============================================================"
  "$@" 2>&1 | tee "$log"
  local code=${PIPESTATUS[0]}
  if [[ $code -ne 0 ]]; then
    echo "ERROR: $label failed with code $code"
    exit "$code"
  fi
}

train_one() {
  local label="$1"
  local out_dir="$2"
  shift 2
  local extra=("$@")
  local final="$out_dir/checkpoint_epoch_$(printf '%03d' "$EPOCHS").pt"

  if [[ -f "$final" ]] && [[ "$(checkpoint_epoch "$final")" -ge "$EPOCHS" ]]; then
    echo "SKIP TRAIN $label: $final already complete"
    return 0
  fi

  local resume=()
  local latest=""
  latest="$(latest_checkpoint "$out_dir" || true)"
  if [[ -n "$latest" && -f "$latest" ]]; then
    resume=(--resume "$latest")
    echo "$label resumes from $latest"
  fi

  run_logged "train_${label}" \
    env LD_LIBRARY_PATH="" python -m "$TRAIN_MODULE" \
      --manifest splits/generated_seed4_mapdims_only.json \
      --split train \
      --model-size default \
      --epochs "$EPOCHS" \
      --batch-size 16 \
      --num-workers 4 \
      --rollout-window 20 \
      --rollout-horizon 5 \
      --window-mode random \
      --samples-per-epoch 50000 \
      --enemy-visibility-mask \
      --enemy-sight-range 9.0 \
      --temporal-loss lambda \
      --td-lambda 0.9 \
      --r2-dyn-scale 1.0 \
      --r2-rep-scale 0.1 \
      --r2-barlow-scale 0.05 \
      --r2-barlow-lambda 0.0005 \
      --r2-latent-normalize \
      --sigreg-weight 0.01 \
      --r2-sigreg-divide-by-dim \
      --r2-sigreg-knots 17 \
      --r2-sigreg-num-proj 1024 \
      --r2-sigreg-proj-chunk 64 \
      --r2-sigreg-max-samples 0 \
      --decoder-weight 0.01 \
      --presence-weight 0.01 \
      --rollout-memory-dim 128 \
      --target-mode full \
      --action-conditioned-memory \
      --one-step-weight 0.5 \
      --lr-warmup-steps 1000 \
      --grad-clip 1.0 \
      --device cuda \
      --amp \
      "${extra[@]}" \
      "${resume[@]}" \
      --out-dir "$out_dir" \
      --wandb \
      --wandb-project SMAC-JEPA-losses \
      --wandb-name "$label"

  if [[ ! -f "$final" ]]; then
    echo "ERROR: expected final checkpoint missing: $final"
    exit 1
  fi
}

eval_one() {
  local label="$1"
  local checkpoint="$2"
  local out_dir="$EVAL_ROOT/$label"
  local summary="$out_dir/eval_seqmem_combined_summary.csv"
  if [[ -f "$summary" && "$FORCE_EVAL" != "1" ]]; then
    echo "SKIP EVAL $label: $summary exists"
    return 0
  fi
  mkdir -p "$out_dir"
  run_logged "eval_${label}" \
    env LD_LIBRARY_PATH="" python "$EVALUATOR" \
      --manifest splits/generated_seed4_mapdims_only.json \
      --split eval \
      --checkpoint "$checkpoint" \
      --out-dir "$out_dir" \
      --probe-dir "$PROBE_DIR" \
      --batch-size 16 \
      --num-workers 4 \
      --max-batches "$EVAL_MAX_BATCHES" \
      --diagnostics \
      --diagnostic-max-batches "$DIAGNOSTIC_MAX_BATCHES" \
      --eval-rollout-horizon 5 \
      --target-mode full \
      --window-mode sequential \
      --thresholds 0.01 0.05 0.1 \
      --probe-decoder \
      --probe-train-split train \
      --probe-epochs "$PROBE_EPOCHS" \
      --probe-max-batches-per-epoch "$PROBE_MAX_BATCHES" \
      --probe-samples-per-epoch "$PROBE_SAMPLES_PER_EPOCH" \
      --probe-lr 0.001 \
      --probe-weight-decay 0.00001 \
      --probe-seed 123 \
      --device cuda \
      --amp
}

EXP16_DIR="runs/rnn_seqmem_exp16_blocker_fixed_full_h5"
EXP17_DIR="runs/rnn_seqmem_exp17_blocker_fixed_ema_full_h5"
EXP18_DIR="runs/rnn_seqmem_exp18_blocker_fixed_ema_memory_barlow_full_h5"
EXP19_DIR="runs/rnn_seqmem_exp19_blocker_fixed_ema_memory_barlow_event_balanced_full_h5"

train_one "rnn-seqmem-exp16-blocker-fixed-full-h5" "$EXP16_DIR" \
  --no-ema-target-encoder \
  --memory-barlow-scale 0.0 \
  --no-event-balanced-sampling
eval_one exp16 "$EXP16_DIR/checkpoint.pt"

train_one "rnn-seqmem-exp17-blocker-fixed-ema-full-h5" "$EXP17_DIR" \
  --ema-target-encoder \
  --ema-momentum 0.996 \
  --memory-barlow-scale 0.0 \
  --no-event-balanced-sampling
eval_one exp17 "$EXP17_DIR/checkpoint.pt"

train_one "rnn-seqmem-exp18-blocker-fixed-ema-memory-barlow-full-h5" "$EXP18_DIR" \
  --ema-target-encoder \
  --ema-momentum 0.996 \
  --memory-barlow-scale 0.01 \
  --no-event-balanced-sampling
eval_one exp18 "$EXP18_DIR/checkpoint.pt"

train_one "rnn-seqmem-exp19-blocker-fixed-ema-memory-barlow-event-balanced-full-h5" "$EXP19_DIR" \
  --ema-target-encoder \
  --ema-momentum 0.996 \
  --memory-barlow-scale 0.01 \
  --event-balanced-sampling \
  --event-fraction 0.30 \
  --event-pool-fraction 0.20 \
  --event-movement-threshold 0.01 \
  --event-state-threshold 0.001 \
  --event-attack-action-min 6 \
  --event-min-transitions 1
eval_one exp19 "$EXP19_DIR/checkpoint.pt"

COMBINED_OUT="$EVAL_ROOT/combined"
mkdir -p "$COMBINED_OUT"
run_logged "eval_combined_exp16_exp19" \
  env LD_LIBRARY_PATH="" python "$EVALUATOR" \
    --manifest splits/generated_seed4_mapdims_only.json \
    --split eval \
    --checkpoint "$EXP16_DIR/checkpoint.pt" \
    --checkpoint "$EXP17_DIR/checkpoint.pt" \
    --checkpoint "$EXP18_DIR/checkpoint.pt" \
    --checkpoint "$EXP19_DIR/checkpoint.pt" \
    --out-dir "$COMBINED_OUT" \
    --probe-dir "$PROBE_DIR" \
    --batch-size 16 \
    --num-workers 4 \
    --max-batches "$EVAL_MAX_BATCHES" \
    --diagnostics \
    --diagnostic-max-batches "$DIAGNOSTIC_MAX_BATCHES" \
    --eval-rollout-horizon 5 \
    --target-mode full \
    --window-mode sequential \
    --thresholds 0.01 0.05 0.1 \
    --probe-decoder \
    --probe-train-split train \
    --probe-epochs "$PROBE_EPOCHS" \
    --probe-max-batches-per-epoch "$PROBE_MAX_BATCHES" \
    --probe-samples-per-epoch "$PROBE_SAMPLES_PER_EPOCH" \
    --probe-lr 0.001 \
    --probe-weight-decay 0.00001 \
    --probe-seed 123 \
    --device cuda \
    --amp

echo
